-- load_stock_item_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.StockItem_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedStockItemData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/stock_item.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Stock Item');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.StockItem_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [WWI Stock Item ID] int,
    [Stock Item] nvarchar(100),
    [Color] nvarchar(20),
    [Selling Package] nvarchar(50),
    [Buying Package] nvarchar(50),
    [Brand] nvarchar(50),
    [Size] nvarchar(20),
    [Lead Time Days] int,
    [Quantity Per Outer] int,
    [Is Chiller Stock] bit,
    [Barcode] nvarchar(50),
    [Tax Rate] decimal(18,3),
    [Unit Price] decimal(18,2),
    [Recommended Retail Price] decimal(18,2),
    [Typical Weight Per Unit] decimal(18,3),
    [Photo] varbinary(max),
    [Valid From] datetime2(7),
    [Valid To] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetStockItemUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.StockItem_Staging ([WWI Stock Item ID], [Stock Item], [Color], [Selling Package], [Buying Package], [Brand], [Size], [Lead Time Days], [Quantity Per Outer], [Is Chiller Stock], [Barcode], [Tax Rate], [Unit Price], [Recommended Retail Price], [Typical Weight Per Unit], [Photo], [Valid From], [Valid To])
SELECT [WWI Stock Item ID], [Stock Item], [Color], [Selling Package], [Buying Package], [Brand], [Size], [Lead Time Days], [Quantity Per Outer], [Is Chiller Stock], [Barcode], [Tax Rate], [Unit Price], [Recommended Retail Price], [Typical Weight Per Unit], [Photo], [Valid From], [Valid To]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedStockItemData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Stock Item', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.StockItem_Staging;
